package com.iboot.pf.module.aps.api.shortage;
import com.iboot.pf.framework.common.util.object.BeanUtils; import com.iboot.pf.framework.datapermission.core.annotation.DataPermission; import com.iboot.pf.module.aps.api.shortage.dto.*; import com.iboot.pf.module.aps.service.shortage.ApsShortageService; import jakarta.annotation.Resource; import org.springframework.stereotype.Service; import org.springframework.validation.annotation.Validated; import java.util.*;
/** APS 缺料 API 实现。 */ @Service @Validated
public class ShortageApiImpl implements ShortageApi { @Resource private ApsShortageService service; @DataPermission(enable=false) public List<ShortageRespDTO> getShortageListByVersionId(Long id){return BeanUtils.toBean(service.getShortageListByVersionId(id),ShortageRespDTO.class);} public void refreshShortage(RefreshShortageReqDTO r){service.refreshShortage(r);} }
